import unittest,re
from tools.kjv_archive import load_register,read
class TitusHouseholdTests(unittest.TestCase):
 def test_households_and_common_salvation(self):
  prior,_=load_register('0.10-kjv.256');lang,manifest=load_register('0.10-kjv.257')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('titus-'):c for c in read(lang.folder/'titus-households-and-common-salvation-cases.json')};self.assertEqual(len(cases),46)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'1:1': ['kjv_paul_acts god servant', 'god choose:psv:pp person:pl faith', 'truth acknowledge:ev'], '1:2': ['eternal life hope', 'god who kjv_lie_false:neg:can', 'before world begin:pa promise:pa'], '1:3': ['in due time:pl', 'to i according_to god ourone/kjv_saviour_timothy', 'entrust:psv:perf'], '1:4': ['my/own son according_to share:psv:adj faith', 'grace mercy and peace', 'ourone/kjv_saviour_timothy'], '1:5': ['i thou:a in kjv_crete_island_acts leave:pa', 'lack:cv thing:pl arrange:should', 'in every city kjv_elder:pl'], '1:6': ['one_num wife husband', 'faithful child:pl', 'kjv_rioting_revel_romans', 'kjv_unruly_thessalonians'], '1:7': ['kjv_bishop_philippians as god steward', 'not self will:cv', 'not soon angry', 'filthy gain:ev'], '1:8': ['kjv_hospitality_romans love:cv', 'good man:pl love:cv', 'kjv_temperance_acts:adj'], '1:9': ['faithful word as he teach:psv:perf', 'kjv_sound_teaching_timothy doctrine', 'kjv_gainsay_romans:cv person:pl'], '1:10': ['vain talk:cv person:pl', 'especially they of kjv_circumcise:ev'], '1:11': ['whose mouth:pl stop:psv:must', 'whole kjv_household:pl kjv_subvert_titus:pr', 'teach:neg:should'], '1:12': ['their/own prophet say:pa', 'kjv_crete_people_acts:pl always', 'idle belly:pl'], '1:13': ['this testimony true be:pr', 'sharply rebuke:imp', 'in faith kjv_sound_integrity_titus'], '1:14': ['kjv_jew:adj fable:pl', 'man:pl command:ev:pl', 'from truth turn:pr'], '1:15': ['to pure person:pl all thing:pl pure', 'nothing pure', 'their/mind and conscience'], '1:16': ['god know:pr profess:pr', 'in work:pl he:a deny:pr', 'kjv_reprobate_romans'], '2:1': ['to kjv_sound_teaching_timothy doctrine fitting be:pr'], '2:2': ['old man:pl', 'dignity:adj kjv_temperance_acts:adj', 'faith in love in patience'], '2:3': ['old woman:pl', 'not falsely accuse:cv', 'not to much wine', 'good thing:pl teach:cv'], '2:4': ['young woman:pl', 'their/husband:pl love:inf', 'their/child:pl love:inf'], '2:5': ['chaste at home keep:cv', 'their/own husband:pl obey:cv', 'kjv_blaspheme:psv:neg:may'], '2:6': ['young man:pl', 'kjv_soberness_acts:adj mind', 'kjv_exhort_romans:imp'], '2:7': ['thyself good work:pl pattern', 'corrupt:neg:ev dignity sincere:ev'], '2:8': ['condemn:psv:neg:can', 'about you say:inf no evil thing'], '2:9': ['servant:pl to their/own master:pl', 'kjv_please_satisfy:inf', 'not against answer:cv'], '2:10': ['not kjv_purloin_titus:cv', 'all good fidelity', 'ourone/kjv_saviour_timothy doctrine adorn:may'], '2:11': ['god grace which salvation bring:pr', 'to all man:pl appear:perf'], '2:12': ['wesg:a teach:cv', 'kjv_ungodly:ev and world:adj desire:pl deny:cv', 'wesg kjv_soberness_acts:adv'], '2:13': ['great god and ourone/kjv_saviour_timothy kjv_jesus_matthew kjv_christ_title', 'glory:adj appear:ev'], '2:14': ['himself for wesg give:pa', 'from all kjv_iniquity', 'to himself kjv_peculiar_possession people'], '2:15': ['with all authority rebuke:imp', 'no man thou:a despise:opt'], '3:1': ['to authority:pl and power:pl submit:inf', 'kjv_magistrate:pl obey:inf'], '3:2': ['no man evil speak:inf', 'no brawl:cv person:pl', 'to all man:pl all kjv_meek_disposition:ev'], '3:3': ['wesg ourselves also former:adv', 'different desire:pl and pleasure:pl serve:cv', 'each other hate:cv'], '3:4': ['god ourone/kjv_saviour_timothy kjv_kindness', 'love towards man appear:pa'], '3:5': ['not by kjv_righteousness work:pl which wesg do:perf', 'according_to his/mercy', 'kjv_regeneration_titus wash:ev and kjv_holy_spirit_title renew:ev'], '3:6': ['on wesg abundance:adv pour:pa', 'through kjv_jesus_matthew kjv_christ_title ourone/kjv_saviour_timothy'], '3:7': ['by his/grace kjv_justify:psv:pp', 'wesg according_to eternal life hope heir:pl'], '3:8': ['i thou sure:adv acknowledge:inf will:pr', 'good work:pl keep:inf heed:adj', 'benefit:adj to man:pl'], '3:9': ['foolish question:pl and kjv_genealogy:pl', 'about law strive:ev:pl', 'benefit:neg:adj and vain'], '3:10': ['after first and second kjv_warn_solemn:ev reject:imp'], '3:11': ['kjv_subvert_titus:psv:perf and sin:pr', 'by himself condemn:psv:cv'], '3:12': ['kjv_artemas_titus or kjv_tychicus_acts', 'to kjv_nicopolis_titus', 'there winter:inf resolve:perf'], '3:13': ['kjv_zenas_titus law know:cv person and kjv_apollos_acts', 'to they:du nothing lack:may'], '3:14': ['they who to wesg belong:pr', 'necessary use:ev:pl', 'fruitless be:neg:may'], '3:15': ['all who with i', 'in faith wesg:a love:pr', 'grace with you all']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('god who kjv_lie_false:neg:can',cases['1-2']['analysis'])
  self.assertIn('grace mercy and peace',cases['1-4']['analysis'])
  self.assertIn('idle belly:pl',cases['1-12']['analysis'])
  self.assertIn('about you say:inf',cases['2-8']['analysis'])
  self.assertIn('to all man:pl appear:perf',cases['2-11']['analysis'])
  self.assertIn('kjv_peculiar_possession people',cases['2-14']['analysis'])
  self.assertIn('wesg ourselves also former:adv',cases['3-3']['analysis'])
  self.assertIn('kjv_regeneration_titus wash:ev',cases['3-5']['analysis'])
  self.assertIn('first and second',cases['3-10']['analysis'])
  self.assertIn('kjv_artemas_titus or kjv_tychicus_acts',cases['3-12']['analysis'])
  self.assertIn('they:du',cases['3-13']['analysis'])
  self.assertIn('grace with you all',cases['3-15']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),8)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
